import React from 'react';
import { FormModal, FormItem, FormLayout, Input } from '@storage-fe/formily-arco';
import { Field } from '@formily/react';
import { Button } from '@arco-design/web-react';

export default () => (
  <Button
    onClick={() => {
      const dialog = FormModal('弹窗表单', () => (
        <FormLayout labelCol={6} wrapperCol={10}>
          <Field name="aaa" required title="输入框1" decorator={[FormItem]} component={[Input]} />
          <Field name="bbb" required title="输入框2" decorator={[FormItem]} component={[Input]} />
          <Field name="ccc" required title="输入框3" decorator={[FormItem]} component={[Input]} />
          <Field name="ddd" required title="输入框4" decorator={[FormItem]} component={[Input]} />
          <FormModal.FooterLeft>
            <span
              onClick={() => {
                dialog.close();
              }}
              style={{ marginLeft: 4 }}
            >
              扩展文案(点击关闭弹窗)
            </span>
          </FormModal.FooterLeft>
        </FormLayout>
      ));
      dialog
        .forOpen((payload, next) => {
          setTimeout(() => {
            next({
              initialValues: {
                aaa: '123',
              },
            });
          }, 1000);
        })
        .forConfirm((payload, next) => {
          setTimeout(() => {
            console.log(payload);
            next(payload);
          }, 1000);
        })
        .forCancel((payload, next) => {
          setTimeout(() => {
            console.log(payload);
            next(payload);
          }, 1000);
        })
        .open()
        .then(console.log);
    }}
  >
    点我打开表单
  </Button>
);
